(D/'site.js').write_text('''const menu=document.querySelector('.menu');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!open));document.querySelector('nav').classList.toggle('open',!open)});const form=document.querySelector('#project-form');if(form){const service=new URLSearchParams(location.search).get('service');if([...form.service.options].some(o=>o.value===service))form.service.value=service;form.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(form);document.querySelector('#summary').value=`Concrete project for RG Contracting Services\\nName: ${data.get('name')}\\nLocation: ${data.get('location')}\\nService: ${form.service.selectedOptions[0].text}\\nProject: ${data.get('details')}`;document.querySelector('#result').hidden=false;document.querySelector('#status').textContent='Your summary is ready. No inquiry has been sent.';});document.querySelector('#copy').addEventListener('click',async()=>{const s=document.querySelector('#summary');try{await navigator.clipboard.writeText(s.value);document.querySelector('#status').textContent='Copied. Save these details for your conversation with Ricardo.'}catch{s.focus();s.select();document.querySelector('#status').textContent='Select and copy the summary above.'}})}''')
print('Generated',len(list(D.rglob('index.html'))),'pages')
